SELECT g.*, s.student_no, u.real_name as student_name, c.course_name, u2.real_name as teacher_name FROM grades g LEFT JOIN students s ON g.student_id = s.id LEFT JOIN users u ON s.user_id = u.id LEFT JOIN courses c ON g.course_id = c.id LEFT JOIN teachers t ON g.teacher_id = t.id LEFT JOIN users u2 ON t.user_id = u2.id
AND s.student_no LIKE CONCAT("%", #{studentNo}, "%")
AND g.course_id = #{courseId}
AND g.semester = #{semester}
LIMIT #{offset}, #{limit}

